<?php
use App\Enums\SupportTicketStatus;use App\Models\Permission;use App\Models\SupportTicket;use App\Models\SupportTicketMessage;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;
uses(RefreshDatabase::class);
function supportStaff(array $permissions): User {$u=User::factory()->create(['email_verified_at'=>now()]);foreach(array_merge(['view_admin'],$permissions) as $n){$p=Permission::query()->firstOrCreate(['name'=>$n],['label'=>ucwords(str_replace('_',' ',$n)),'group_name'=>'Support']);$u->permissions()->syncWithoutDetaching($p);}return $u;}
it('blocks users without support permission',function(){$this->actingAs(supportStaff([]))->get('/admin/support/tickets')->assertForbidden();});
it('allows staff to view queues and details',function(){$u=supportStaff(['view_support_tickets']);$t=SupportTicket::factory()->create();$this->actingAs($u)->get('/admin/support/tickets')->assertOk();$this->actingAs($u)->get("/admin/support/tickets/{$t->uuid}")->assertOk();});
it('separates replies from internal notes',function(){$u=supportStaff(['view_support_tickets','reply_support_tickets','add_support_internal_notes']);$t=SupportTicket::factory()->create(['status'=>SupportTicketStatus::Open]);$this->actingAs($u)->post("/admin/support/tickets/{$t->uuid}/reply",['body'=>'Customer reply'])->assertRedirect();$this->actingAs($u)->post("/admin/support/tickets/{$t->uuid}/notes",['body'=>'Private note'])->assertRedirect();expect(SupportTicketMessage::where('body','Customer reply')->first()->is_customer_visible)->toBeTrue();expect(SupportTicketMessage::where('body','Private note')->first()->is_customer_visible)->toBeFalse();});
it('records operational changes',function(){$u=supportStaff(['view_support_tickets','manage_support_tickets']);$a=supportStaff(['view_support_tickets']);$t=SupportTicket::factory()->create(['status'=>SupportTicketStatus::Open]);$this->actingAs($u)->patch("/admin/support/tickets/{$t->uuid}",['assigned_user_id'=>$a->id,'priority'=>'high','status'=>'in_progress'])->assertRedirect();$t->refresh();expect($t->assigned_user_id)->toBe($a->id)->and($t->priority->value)->toBe('high')->and($t->status->value)->toBe('in_progress');expect($t->statusHistories()->count())->toBeGreaterThanOrEqual(3);});
